  (options.client ?? client).get<GetWalletResponses, GetWalletErrors, ThrowOnError>({
    url: "/v1/wallets/{identity}",
    ...options,
  });

/**
 * List issued, owned, and possessed assets for a wallet
 *
 * Asset lists from one peer connection, filtered by kind. Use kind=all for a single round trip.
 */
export const listWalletAssets = <ThrowOnError extends boolean = false>(
  options: Options<ListWalletAssetsData, ThrowOnError>,
): RequestResult<ListWalletAssetsResponses, ListWalletAssetsErrors, ThrowOnError> =>
  (options.client ?? client).get<ListWalletAssetsResponses, ListWalletAssetsErrors, ThrowOnError>({
    url: "/v1/wallets/{identity}/assets",
    ...options,
  });

